// Title: How to embed JavaScript in an SVG worksheet generated by Aspose.Cells for .NET to create hover tooltips
// Common Searches: C# add JavaScript hover tooltip to SVG output from Aspose.Cells | Aspose.Cells render worksheet as SVG with interactive cell tooltips | Inject script block into Aspose.Cells generated SVG using C# | Add data-tooltip attribute to SVG text elements produced by Aspose.Cells | Create responsive SVG workbook with tooltip support in .NET
// Tags: Aspose.Cells SVG rendering with JavaScript | embed script in Aspose.Cells generated SVG | hover tooltip for Excel cell SVG | modify SVG output using C# Regex | data-tooltip attribute for SVG text elements | responsive SVG workbook Aspose.Cells

using System;
using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using Aspose.Cells;
using Aspose.Cells.Drawing;
using Aspose.Cells.Rendering;

namespace AsposeCellsSvgTooltipDemo
{
    // The example creates a workbook, fills it with sample data, calculates formulas, and renders the first worksheet to an SVG stream using Aspose.Cells. It then reads the SVG as a UTF‑8 string, inserts a <script> block that implements mouseover/mouseout tooltip logic, adds a hidden <text> element to act as the tooltip container, and uses a regular expression to append a data-tooltip attribute to each cell's <text> element. The modified SVG with interactive hover tooltips is saved to the specified file.
    class Program
    {
        static void Main(string[] args)
        {
            try
            {
                // Output file name (can be overridden by command‑line argument)
                string outputSvgPath = args.Length > 0 ? args[0] : "WorkbookWithTooltips.svg";

                // -----------------------------------------------------------------
                // 1. Create a workbook and populate it with sample data
                // -----------------------------------------------------------------
                Workbook workbook = new Workbook();
                Worksheet sheet = workbook.Worksheets[0];

                // Header row
                sheet.Cells["A1"].PutValue("Product");
                sheet.Cells["B1"].PutValue("Price");
                sheet.Cells["C1"].PutValue("Quantity");

                // Sample rows
                sheet.Cells["A2"].PutValue("Apple");
                sheet.Cells["B2"].PutValue(1.20);
                sheet.Cells["C2"].PutValue(10);

                sheet.Cells["A3"].PutValue("Banana");
                sheet.Cells["B3"].PutValue(0.80);
                sheet.Cells["C3"].PutValue(15);

                sheet.Cells["A4"].PutValue("Cherry");
                sheet.Cells["B4"].PutValue(2.50);
                sheet.Cells["C4"].PutValue(8);

                // Add a simple total formula
                sheet.Cells["B5"].Formula = "=SUM(B2:B4)";
                sheet.Cells["C5"].Formula = "=SUM(C2:C4)";
                sheet.Cells["A5"].PutValue("Total");

                // Calculate formulas so that values are present in the SVG
                workbook.CalculateFormula();

                // -----------------------------------------------------------------
                // 2. Save the worksheet as SVG into a memory stream
                // -----------------------------------------------------------------
                // Use SvgImageOptions (recommended) instead of the obsolete SVGFitToViewPort property
                SvgImageOptions svgOptions = new SvgImageOptions
                {
                    ImageType = ImageType.Svg,
                    OnePagePerSheet = true,
                    FitToViewPort = true // makes the SVG responsive
                };

                using (MemoryStream svgStream = new MemoryStream())
                {
                    // Render the first (and only) page of the worksheet to SVG
                    SheetRender renderer = new SheetRender(sheet, svgOptions);
                    renderer.ToImage(0, svgStream);
                    svgStream.Position = 0;

                    // Read the SVG content as a UTF‑8 string
                    string svgContent;
                    using (StreamReader reader = new StreamReader(svgStream, Encoding.UTF8))
                    {
                        svgContent = reader.ReadToEnd();
                    }

                    // -----------------------------------------------------------------
                    // 3. Inject JavaScript for interactive tooltips
                    // -----------------------------------------------------------------
                    const string scriptBlock = @"
    <script type=""text/ecmascript""><![CDATA[
        // Simple tooltip implementation for SVG text elements
        function showTooltip(evt) {
            var tooltip = document.getElementById('tooltip');
            var target = evt.target;
            var tip = target.getAttribute('data-tooltip');
            if (!tip) return;
            tooltip.textContent = tip;
            var pt = target.ownerSVGElement.createSVGPoint();
            pt.x = evt.clientX;
            pt.y = evt.clientY;
            var svgP = pt.matrixTransform(target.getScreenCTM().inverse());
            tooltip.setAttribute('x', svgP.x + 10);
            tooltip.setAttribute('y', svgP.y + 10);
            tooltip.setAttribute('visibility', 'visible');
        }

        function hideTooltip(evt) {
            var tooltip = document.getElementById('tooltip');
            tooltip.setAttribute('visibility', 'hidden');
        }

        // Attach listeners to all text elements after the document loads
        document.addEventListener('DOMContentLoaded', function () {
            var texts = document.getElementsByTagName('text');
            for (var i = 0; i < texts.length; i++) {
                var txt = texts[i];
                if (txt.id === 'tooltip') continue;
                txt.addEventListener('mouseover', showTooltip);
                txt.addEventListener('mouseout', hideTooltip);
            }
        });
    ]]></script>";

                    // Insert the script block right after the opening <svg> tag
                    int svgTagEnd = svgContent.IndexOf('>');
                    if (svgTagEnd == -1)
                    {
                        Console.WriteLine("Failed to locate the opening <svg> tag.");
                        return;
                    }
                    svgContent = svgContent.Insert(svgTagEnd + 1, scriptBlock);

                    // Add a hidden <text> element that will act as the tooltip container
                    const string tooltipElement = @"<text id=""tooltip"" visibility=""hidden"" font-family=""Arial"" font-size=""12"" fill=""black""></text>";
                    int closeTagPos = svgContent.LastIndexOf("</svg>", StringComparison.OrdinalIgnoreCase);
                    if (closeTagPos == -1)
                    {
                        Console.WriteLine("Failed to locate the closing </svg> tag.");
                        return;
                    }
                    svgContent = svgContent.Insert(closeTagPos, tooltipElement);

                    // Add a data-tooltip attribute to each <text> element that represents a cell
                    svgContent = Regex.Replace(
                        svgContent,
                        @"<text([^>]*?)>(.*?)</text>",
                        match =>
                        {
                            string attributes = match.Groups[1].Value;
                            string innerText = match.Groups[2].Value;

                            // Extract the id attribute if present (cell address)
                            string idMatch = Regex.Match(attributes, @"id\s*=\s*""([^""]+)""").Groups[1].Value;
                            string tooltip = string.IsNullOrEmpty(idMatch)
                                ? $"Tooltip: {innerText}"
                                : $"Cell {idMatch}: {innerText}";

                            // Append data-tooltip if not already present
                            if (!attributes.Contains("data-tooltip"))
                            {
                                attributes += $" data-tooltip=\"{tooltip}\"";
                            }

                            return $"<text{attributes}>{innerText}</text>";
                        },
                        RegexOptions.Singleline);

                    // -----------------------------------------------------------------
                    // 4. Write the modified SVG to the output file
                    // -----------------------------------------------------------------
                    // Ensure the directory exists
                    string outputDir = Path.GetDirectoryName(Path.GetFullPath(outputSvgPath));
                    if (!string.IsNullOrEmpty(outputDir) && !Directory.Exists(outputDir))
                    {
                        Directory.CreateDirectory(outputDir);
                    }

                    File.WriteAllText(outputSvgPath, svgContent, Encoding.UTF8);
                    Console.WriteLine($"SVG file with interactive tooltips saved to: {outputSvgPath}");
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"An error occurred: {ex.Message}");
            }
        }
    }
}
